from std_msgs.msg import Float64MultiArray
from eai_manipulator_msgs.msg import ArmTargetPose, DualArmTargetPose


class TopicMonitorConfig:
    """Topic监控配置基类"""
    def __init__(self, topic_name, msg_type, controller_name, timeout_sec=0.05):
        self.topic_name = topic_name
        self.msg_type = msg_type
        self.controller_name = controller_name
        self.timeout_sec = timeout_sec


# Topic配置注册表 - 在此添加新的topic类型
TOPIC_CONFIGS = {
    # JointSpace topics
    '/jointspace_commands_L': TopicMonitorConfig('/jointspace_commands_L', Float64MultiArray, 'jointspace_arm_L_controller'),
    '/jointspace_commands_R': TopicMonitorConfig('/jointspace_commands_R', Float64MultiArray, 'jointspace_arm_R_controller'),
    '/jointspace_commands_L_collisionfree': TopicMonitorConfig('/jointspace_commands_L_collisionfree', Float64MultiArray, 'jointspace_single_arm_qpik_L_controller'),
    '/jointspace_commands_R_collisionfree': TopicMonitorConfig('/jointspace_commands_R_collisionfree', Float64MultiArray, 'jointspace_single_arm_qpik_R_controller'),
    '/jointspace_commands_Dual': TopicMonitorConfig('/jointspace_commands_Dual', Float64MultiArray, 'jointspace_ruckig_qp_controller'),
    '/jointspace_commands_body': TopicMonitorConfig('/jointspace_commands_body', Float64MultiArray, 'jointspace_body_controller'),
    '/jointspace_commands_head': TopicMonitorConfig('/jointspace_commands_head', Float64MultiArray, 'jointspace_head_controller'),
    '/jointspace_commands_waist_pitch': TopicMonitorConfig('/jointspace_commands_waist_pitch', Float64MultiArray, 'jointspace_waist_pitch_controller'),
    '/jointspace_commands_waist_yaw': TopicMonitorConfig('/jointspace_commands_waist_yaw', Float64MultiArray, 'jointspace_waist_yaw_controller'),
    '/jointspace_commands_body3joints': TopicMonitorConfig('/jointspace_commands_body3joints', Float64MultiArray, 'jointspace_body3joints_controller'),
    # EndPose topics
    '/endposetarget_L': TopicMonitorConfig('/endposetarget_L', ArmTargetPose, 'endpose_single_arm_qp_L_controller'),
    '/endposetarget_R': TopicMonitorConfig('/endposetarget_R', ArmTargetPose, 'endpose_single_arm_qp_R_controller'),
    '/endposetarget_Dual': TopicMonitorConfig('/endposetarget_Dual', DualArmTargetPose, 'endpose_dual_arm_qp_controller'),
    '/endposetarget_Body': TopicMonitorConfig('/endposetarget_Body', Float64MultiArray, 'endpose_body_controller'),
    '/endposetarget_Head': TopicMonitorConfig('/endposetarget_Head', Float64MultiArray, 'endpose_head_controller'),
    '/endposetarget_Wholebody': TopicMonitorConfig('/endposetarget_Wholebody', DualArmTargetPose, 'endpose_wholebody_controller'),
}


def get_all_topic_configs():
    """获取所有注册的topic配置"""
    return TOPIC_CONFIGS


def get_topic_controller_map():
    """获取 topic_name -> controller_name 映射"""
    return {name: config.controller_name for name, config in TOPIC_CONFIGS.items()}


# topic -> controller 映射
topic_controller_map = get_topic_controller_map()
# controller -> topic 映射
controller_topic_map = {v: k for k, v in topic_controller_map.items()}
